def normalize_valuation_terms(text):
    # Statistical CIF values in Comext are not silently equated to customs value.
    for old,new in [('Средняя таможенная стоимость','Средняя статистическая стоимость'),
                    ('средняя таможенная стоимость','средняя статистическая стоимость'),
                    ('средней таможенной стоимости','средней статистической стоимости'),
                    ('среднюю таможенную стоимость','среднюю статистическую стоимость'),
                    ('отношение таможенной стоимости','отношение статистической стоимости'),
                    ('Таможенная стоимость относится','Статистическая стоимость относится'),
                    ('подмены цены таможенной стоимостью','подмены цены статистической стоимостью')]:
        text=text.replace(old,new)
    return text


